arguments.command:
mkdir notes
cat > notes/PRC-501.md <<'E'
# PRC-501
原因: ee322d6 "tidy up rounding" が切り捨てを切り上げ（+99）に変えた。bin/price, bin/quote, lib/invoice.sh の3か所に同じ式がある。
計画: 3か所とも `$1 * 90 / 100` に戻す。999 -> 899 のテストを追加。quote/invoice も検証する。
E
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash -c 'source lib/invoice.sh 999' 2>&1)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo rc=$?
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo rc=$?; git diff --stat

